namespace Aurora {
public sealed class RestartState {public bool Required,Unknown;public string[] Reasons=new string[0];}
public static class RestartProbe {
    public static RestartState Read(){var state=new RestartState();var reasons=new List<string>();foreach(var keyPath in new[]{@"SOFTWARE\Microsoft\Windows\CurrentVersion\Component Based Servicing\RebootPending",@"SOFTWARE\Microsoft\Windows\CurrentVersion\WindowsUpdate\Auto Update\RebootRequired"})try{using(var root=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,Environment.Is64BitOperatingSystem?RegistryView.Registry64:RegistryView.Registry32))using(var key=root.OpenSubKey(keyPath)){if(key!=null){state.Required=true;reasons.Add(keyPath.Contains("Component Based")?L.T("Componentes do Windows aguardam reinicialização.","Windows components are waiting for a restart."):L.T("O Windows Update solicita reinicialização.","Windows Update requests a restart."));}}}catch{state.Unknown=true;}try{using(var key=Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Control\Session Manager")){var pending=key==null?null:key.GetValue("PendingFileRenameOperations") as string[];if(pending!=null&&pending.Any(x=>!String.IsNullOrWhiteSpace(x)))reasons.Add(L.T("Há operações de arquivos agendadas para o próximo início.","There are file operations scheduled for next startup."));}}catch{state.Unknown=true;}state.Reasons=reasons.ToArray();return state;}
}
public partial class MainWindow {
    readonly Dictionary<int,WorkProgress> jobProgress=new Dictionary<int,WorkProgress>();
    readonly List<OperationRecord> completedOperations=new List<OperationRecord>();
    Button activityButton,restartButton;RestartState restartState=new RestartState();DispatcherTimer restartTimer;bool restartRequested;
    void AddActivityControls(Panel footer){var row=new WrapPanel{Margin=new Thickness(14,0,10,0)};activityButton=Button(T("Atividades e resultados","Activity and results"),ShowActivities);activityButton.Padding=new Thickness(9,5,9,5);activityButton.FontSize=12;row.Children.Add(activityButton);restartButton=Button(T("Reinicialização","Restart status"),ShowRestartStatus);restartButton.Padding=new Thickness(9,5,9,5);restartButton.FontSize=12;restartButton.Visibility=restartState.Reasons.Length>0?Visibility.Visible:Visibility.Collapsed;row.Children.Add(restartButton);footer.Children.Add(row);}
    void ApplyProgress(int id,WorkProgress value){if(!activeJobs.ContainsKey(id))return;jobProgress[id]=value;if(!String.IsNullOrWhiteSpace(value.Stage))activeJobs[id]=Tuple.Create(value.Stage,activeJobs[id].Item2);UpdateWorkUi();}
    void StartTrackedWork(string title,Func<string> action,Action<string> finished){string key=UiLanguage.English(title);if(activeJobKeys.Values.Any(x=>x==key)){status.Text=T("Esta tarefa já está em andamento: ","This task is already running: ")+title;return;}int id=++nextJobId;string group=Guid.NewGuid().ToString("N");activeJobKeys[id]=key;activeJobs[id]=Tuple.Create(title,DateTime.Now);var record=new OperationRecord{Id=group,Title=title,Started=DateTime.UtcNow};status.Text=title+"…";status.Foreground=Accent;UpdateWorkUi();
        Task.Factory.StartNew(()=>{workerJobId=id;var throttle=Stopwatch.StartNew();WorkReporting.Sink=value=>{if(throttle.ElapsedMilliseconds<130&&value.Total>0&&value.Done<value.Total)return;throttle.Restart();if(!Dispatcher.HasShutdownStarted)Dispatcher.BeginInvoke(new Action(()=>ApplyProgress(id,value)));};Journal.SetOperation(group,title);try{record.Before=MaintenanceSample.Read();record.Result=OperationLanes.Execute(title,()=>{ReportStage(title);return action();},()=>ReportStage(T("Na fila: ","Queued: ")+title));}catch(OperationCanceledException){record.Result=T("Cancelado pelo usuário.","Canceled by user.");}catch(Exception error){record.Result="ERROR • "+error.Message;}finally{record.After=MaintenanceSample.Read();record.Finished=DateTime.UtcNow;WorkReporting.Sink=null;Journal.SetOperation(null,null);workerJobId=0;}try{journal.Log(title,record.Result);journal.SaveOperation(record);}catch{}return record;
        }).ContinueWith(task=>{if(Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke(new Action(()=>{activeJobs.Remove(id);activeJobKeys.Remove(id);jobProgress.Remove(id);var done=task.Result;completedOperations.Insert(0,done);if(completedOperations.Count>60)completedOperations.RemoveAt(completedOperations.Count-1);UpdateWorkUi();status.Text=(done.Failed?T("Não foi possível concluir: ","Could not complete: "):T("Operação concluída: ","Operation finished: "))+UiLanguage.Current(title);status.Foreground=CompletionBrush(done.Result);try{if(finished!=null)finished(done.Result);}catch(Exception error){try{journal.Log(title,"ERROR • UI callback • "+error);}catch{}status.Text=T("Não foi possível atualizar o resultado: ","Could not update the result: ")+UiLanguage.Current(title);status.Foreground=OutcomeBrush("ERROR");ShowNotice("ERROR • "+error.Message);}if(!preview&&System.Text.RegularExpressions.Regex.IsMatch(done.Result??"",@"(?i)reboot\s*(?:required|needed)\s*[:=]?\s*(?:true|yes)|reinicializa[çc][aã]o necess[aá]ria|restart required"))RememberRestart(title);if(!preview)RefreshRestartStatus();}));});
    }
    void InitializeNextExperience(){InstallKeyboardSupport();if(preview)return;RefreshRestartStatus();restartTimer=new DispatcherTimer{Interval=TimeSpan.FromMinutes(5)};restartTimer.Tick+=(s,e)=>RefreshRestartStatus();restartTimer.Start();Closed+=(s,e)=>{if(restartTimer!=null)restartTimer.Stop();};StartBrowserDetection();StartOuOUpdateCheck(false);OfferSensorSetup();}
    string RestartFile{get{return Path.Combine(journal.Folder,"restart-notes.xml");}}
    void RememberRestart(string title){try{var x=File.Exists(RestartFile)?XElement.Load(RestartFile):new XElement("restart",new XAttribute("boot",machine==null?"":machine.BootTime));if(!x.Elements("reason").Any(e=>e.Value==title))x.Add(new XElement("reason",title));AtomicFiles.SaveXml(x,RestartFile);}catch{}}
    void RefreshRestartStatus(){if(preview)return;Task.Factory.StartNew(()=>{var state=RestartProbe.Read();try{if(File.Exists(RestartFile)){var x=XElement.Load(RestartFile);string boot=(string)x.Attribute("boot");if(!String.IsNullOrEmpty(boot)&&machine!=null&&!String.IsNullOrEmpty(machine.BootTime)&&boot!=machine.BootTime)File.Delete(RestartFile);else{state.Reasons=state.Reasons.Concat(x.Elements("reason").Select(e=>L.T("Solicitado por: ","Requested by: ")+e.Value)).Distinct().ToArray();state.Required|=x.Elements("reason").Any();}}}catch{state.Unknown=true;}return state;}).ContinueWith(task=>{if(Dispatcher.HasShutdownStarted)return;Dispatcher.BeginInvoke(new Action(()=>{if(task.IsFaulted)return;restartState=task.Result;if(restartButton!=null){restartButton.Visibility=restartState.Reasons.Length>0?Visibility.Visible:Visibility.Collapsed;restartButton.Content=restartState.Required?T("↻ Reinicialização pendente","↻ Restart pending"):T("↻ Operações no próximo início","↻ Next-startup operations");}}));});}
    void ShowRestartStatus(){var d=ToolWindow(T("Reinicialização","Restart status"),620,420);var p=new StackPanel{Margin=new Thickness(20)};p.Children.Add(Text(T("Reinicialização do computador","Computer restart"),22,Accent));foreach(string reason in restartState.Reasons)p.Children.Add(Text("• "+reason,14,Ink));if(restartState.Unknown)p.Children.Add(Text(T("Algumas informações não puderam ser consultadas.","Some information could not be queried."),13,Muted));if(restartState.Reasons.Length==0)p.Children.Add(Text(T("Nenhuma solicitação foi identificada nesta consulta.","No request was identified in this check."),14,Ink));Row(p,Button(T("Reiniciar depois","Restart later"),()=>d.Close()),Button(T("Reiniciar em 60 segundos","Restart in 60 seconds"),()=>{if(activeJobs.Count>0){ShowToast(T("Conclua as tarefas do OuO antes de reiniciar.","Complete OuO tasks before restarting."));return;}if(!Confirm(T("Salve seus documentos. Reiniciar o Windows em 60 segundos?","Save your documents. Restart Windows in 60 seconds?")))return;var r=Runner.Run(Path.Combine(Environment.SystemDirectory,"shutdown.exe"),"/r /t 60",10000);if(r.Code==0){restartRequested=true;d.Close();ShowToast(T("Reinicialização agendada. Você pode cancelá-la em Reinicialização.","Restart scheduled. You can cancel it in Restart status."));}else ShowNotice(Describe(r));}),Button(T("Cancelar reinicialização agendada pelo OuO","Cancel restart scheduled by OuO"),()=>{if(!restartRequested)return;var r=Runner.Run(Path.Combine(Environment.SystemDirectory,"shutdown.exe"),"/a",10000);if(r.Code==0)restartRequested=false;ShowNotice(Describe(r));}));d.Content=WindowFrame(p);d.ShowDialog();}
    void ShowActivities(){var d=ToolWindow(T("Atividades e resultados","Activity and results"),780,620);var p=new StackPanel{Margin=new Thickness(18)};p.Children.Add(Text(T("Em andamento","In progress"),22,Accent));var live=new StackPanel();p.Children.Add(live);Action render=()=>{live.Children.Clear();foreach(var item in activeJobs){WorkProgress progress;bool known=jobProgress.TryGetValue(item.Key,out progress)&&progress.Total>0;live.Children.Add(Text(known?progress.Label:item.Value.Item1+T(" • total ainda desconhecido"," • total not known yet"),14,Ink));live.Children.Add(new ProgressBar{Height=8,Margin=new Thickness(0,0,0,9),Foreground=Accent,IsIndeterminate=!known,Value=known?progress.Percent:0});}if(activeJobs.Count==0)live.Children.Add(Text(T("Nenhuma tarefa em andamento.","No task in progress."),13,Muted));};render();var tick=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(500)};tick.Tick+=(s,e)=>render();tick.Start();d.Closed+=(s,e)=>tick.Stop();p.Children.Add(Text(T("Resultados recentes","Recent results"),20,Accent));foreach(var record in completedOperations.Take(12)){var entry=new StackPanel{Margin=new Thickness(0,3,0,12)};entry.Children.Add(Text(ResultSymbol(record.Result)+record.ToString(),14,OutcomeBrush(record.Result)));entry.Children.Add(Text(record.Summary,12,Muted));var captured=record;Row(entry,Button(T("Ver resultado","View result"),()=>ShowNotice(captured.Result,captured.Title)),Button(T("Preparar relatório","Prepare report"),()=>ReportProblem(captured.Title,captured.Result+"\n"+captured.Summary)));p.Children.Add(entry);}Row(p,Button(T("Fechar","Close"),()=>d.Close()));d.Content=WindowFrame(p);d.ShowDialog();}
    void ReportProblem(string title,string result){var d=ToolWindow(T("Revisar relatório","Review report"),760,600);var p=new StackPanel{Margin=new Thickness(18)};p.Children.Add(Text(T("Relatório para suporte","Support report"),22,Accent));p.Children.Add(Text(T("Revise o conteúdo antes de compartilhar. Caminhos, e-mails e credenciais reconhecíveis são removidos; outros detalhes podem precisar de revisão manual.","Review the content before sharing. Recognizable paths, emails and credentials are removed; other details may need manual review."),13,Muted));var input=Input(DiagnosticPrivacy.Build(title,result,machine==null?"":machine.Caption+" • "+machine.Arch+" • "+machine.Build,OuOUpdates.Current.ToString()));input.AcceptsReturn=true;input.TextWrapping=TextWrapping.Wrap;input.VerticalScrollBarVisibility=ScrollBarVisibility.Auto;input.Height=330;p.Children.Add(input);Row(p,Button(T("Copiar relatório","Copy report"),()=>{try{Clipboard.SetText(input.Text);ShowToast(T("Relatório copiado.","Report copied."));}catch(Exception e){ShowNotice(e.Message);}}),Button(T("Salvar relatório","Save report"),()=>{var save=new SaveFileDialog{Filter="Texto (*.txt)|*.txt",FileName="OuO-relatorio-"+DateTime.Now.ToString("yyyyMMdd-HHmm")+".txt"};if(save.ShowDialog(d)==true){File.WriteAllText(save.FileName,input.Text,Encoding.UTF8);ShowToast(T("Relatório salvo.","Report saved."));}}),Button(T("Fechar","Close"),()=>d.Close()));d.Content=WindowFrame(p);d.ShowDialog();}
    void ChangeHistoryCard(){var card=Card(T("Restaurar uma operação","Restore an operation"),T("Escolha o conjunto de alterações. O OuO confere se houve mudanças posteriores antes de restaurar os valores salvos.","Choose a set of changes. OuO checks for later changes before restoring saved values."));var groups=new ListBox{MinHeight=90,MaxHeight=260,Background=Bg,Foreground=Ink};var all=journal.ChangeGroups();foreach(var group in all)groups.Items.Add(group);card.Children.Add(groups);if(all.Count==0)card.Children.Add(Text(T("Nenhum conjunto de alterações disponível.","No group of changes is available."),13,Muted));var result=Input("");result.IsReadOnly=true;result.AcceptsReturn=true;result.TextWrapping=TextWrapping.Wrap;result.Height=140;Row(card,Button(T("Desfazer esta operação","Undo this operation"),()=>{var selected=groups.SelectedItem as ChangeGroup;if(selected==null){ShowToast(T("Selecione uma operação.","Select an operation."));return;}if(selected.Admin&&!RequireAdmin())return;if(!Confirm(T("Restaurar as alterações desta operação?\n","Restore this operation's changes?\n")+selected))return;Work(T("Restaurar operação selecionada","Restore selected operation"),()=>journal.UndoGroup(selected.Id),r=>{result.Text=r;groups.Items.Clear();foreach(var item in journal.ChangeGroups())groups.Items.Add(item);});}));AttachResult(card,result);}
    void OperationHistoryCard(){var card=Card(T("Operações e comparação antes/depois","Operations and before/after comparison"),T("Os últimos 100 resultados ficam disponíveis mesmo após fechar o OuO.","The latest 100 results remain available after closing OuO."));var records=new ListBox{MinHeight=90,MaxHeight=220,Background=Bg,Foreground=Ink};foreach(var item in journal.OperationResults())records.Items.Add(item);card.Children.Add(records);var details=Input("");details.IsReadOnly=true;details.AcceptsReturn=true;details.TextWrapping=TextWrapping.Wrap;details.Height=220;records.SelectionChanged+=(s,e)=>{var selected=records.SelectedItem as OperationRecord;if(selected!=null)details.Text=selected+"\n\n"+selected.Summary+"\n"+selected.Result;};AttachResult(card,details);if(records.Items.Count>0)records.SelectedIndex=0;else card.Children.Add(Text(T("As próximas operações aparecerão aqui.","Your next operations will appear here."),13,Muted));}
